681	template<typename Storage>
682	KeeperSnapshotManager<Storage>::KeeperSnapshotManager(
683	    size_t snapshots_to_keep_,
684	    const KeeperContextPtr & keeper_context_,
685	    bool compress_snapshots_zstd_,
686	    const std::string & superdigest_,
687	    size_t storage_tick_time_)
688	    : snapshots_to_keep(snapshots_to_keep_)
689	    , compress_snapshots_zstd(compress_snapshots_zstd_)
690	    , superdigest(superdigest_)
691	    , storage_tick_time(storage_tick_time_)
692	    , keeper_context(keeper_context_)
693	{
694	    std::unordered_set<DiskPtr> read_disks;
695	    const auto load_snapshot_from_disk = [&](const auto & disk)
696	    {
697	        if (read_disks.contains(disk))
698	            return;
699	
700	        LOG_TRACE(log, "Reading from disk {}", disk->getName());
701	        std::unordered_map<std::string, std::string> incomplete_files;
702	
703	        const auto clean_incomplete_file = [&](const auto & file_path)
704	        {
705	            if (auto incomplete_it = incomplete_files.find(fs::path(file_path).filename()); incomplete_it != incomplete_files.end())
706	            {
707	                LOG_TRACE(log, "Removing {} from {}", file_path, disk->getName());
708	                disk->removeFile(file_path);
709	                disk->removeFile(incomplete_it->second);
710	                incomplete_files.erase(incomplete_it);
711	                return true;
712	            }
713	
714	            return false;
715	        };
716	
717	        std::vector<std::string> snapshot_files;
718	        for (auto it = disk->iterateDirectory(""); it->isValid(); it->next())
719	        {
720	            if (it->name().starts_with(tmp_keeper_file_prefix))
721	            {
722	                incomplete_files.emplace(it->name().substr(tmp_keeper_file_prefix.size()), it->path());
723	                continue;
724	            }
725	
726	            if (it->name().starts_with("snapshot_") && !clean_incomplete_file(it->path()))
727	                snapshot_files.push_back(it->path());
728	        }
729	
730	        for (const auto & snapshot_file : snapshot_files)
731	        {
732	            if (clean_incomplete_file(fs::path(snapshot_file).filename()))
733	                continue;
734	
735	            LOG_TRACE(log, "Found {} on {}", snapshot_file, disk->getName());
736	            size_t snapshot_up_to = getSnapshotPathUpToLogIdx(snapshot_file);
737	            auto [_, inserted] = existing_snapshots.insert_or_assign(snapshot_up_to, std::make_shared<SnapshotFileInfo>(snapshot_file, disk));
738	
739	            if (!inserted)
740	                LOG_WARNING(
741	                    log,
742	                    "Found another snapshots with last log idx {}, will use snapshot from disk {}",
743	                    snapshot_up_to,
744	                    disk->getName());
745	        }
746	
747	        for (const auto & [name, path] : incomplete_files)
748	            disk->removeFile(path);
749	
750	        if (snapshot_files.empty())
751	            LOG_TRACE(log, "No snapshots were found on {}", disk->getName());
752	
753	        read_disks.insert(disk);
754	    };
755	
756	    for (const auto & disk : keeper_context->getOldSnapshotDisks())
757	        load_snapshot_from_disk(disk);
758	
759	    auto disk = getDisk();
760	    load_snapshot_from_disk(disk);
761	
762	    auto latest_snapshot_disk = getLatestSnapshotDisk();
763	    if (latest_snapshot_disk != disk)
764	        load_snapshot_from_disk(latest_snapshot_disk);
765	
766	    removeOutdatedSnapshotsIfNeeded();
767	    moveSnapshotsIfNeeded();
768	}
